# solution.py
def solution(input_str):
    import sys
    from collections import defaultdict
    from functools import lru_cache

    lines = input_str.strip().split('\n')
    if not lines:
        return '0'

    n, m = map(int, lines[0].split())
    events = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        if parts[0] == '1':
            events.append((1,))
        else:
            events.append((2, parts[1]))

    # Build list of intervals: index from 0 to k (k is number of type 1 minus 1)
    type1_indices = [0]  # Index 0 is the first type 1 event (first line of events)
    current_interval_events = defaultdict(list)

    current_interval = 0
    friend_map = defaultdict(list)  # friend -> list of intervals they visit

    for i in range(n):
        if events[i][0] == 1:
            # Reset for new interval
            current_interval += 1
            # Save previous interval if it has friend visits
            for friend, intervals in friend_map.items():
                if not intervals:  # Add intervals for non-empty ones
                    pass
            type1_indices.append(i)
            friend_map.clear()
        else:
            friend = events[i][1]
            friend_map[friend].append(current_interval)

    # Build friend list
    # Collect all friends that appear at least once
    all_friends = sorted(friend_map.keys())
    rank = {}
    for i, f in enumerate(all_friends):
        rank[f] = i

    m_actual = len(all_friends)

    if m_actual == 0:
        return '0'

    # Build compatibility: conflict[i][j] = 1 if friends i and j appear in same interval
    conflict_matrix = [[0] * m_actual for _ in range(m_actual)]
    for friend in all_friends:
        for interval in friend_map[friend]:
            for other in friend_map:
                if other != friend:
                    for other_interval in friend_map[other]:
                        if interval == other_interval:
                            conflict_matrix[rank[friend]][rank[other]] = 1
                            conflict_matrix[rank[other]][rank[friend]] = 1

    # Maximum independent set using recursive search with pruning
    best_count = 0

    @lru_cache(maxsize=10000)
    def solve(index, selected_mask):
        nonlocal best_count

        # If current selection exceeds best, return
        count = bin(selected_mask).count('1')
        if count > best_count:
            best_count = count

        # If we've checked all friends
        if index == len(all_friends):
            if count > best_count:
                best_count = count
            return count

        # Try including friend at index if possible
        friend_idx = index
        new_mask = selected_mask | (1 << friend_idx)

        # Check if adding this friend is valid (no conflict with already selected friends)
        can_add = True
        for bit in range(friend_idx):
            if (selected_mask >> bit) & 1:
                if conflict_matrix[friend_idx][bit] == 1:
                    can_add = False
                    break

        # Try adding
        if can_add:
            solve(friend_idx + 1, new_mask)

        # Try not adding
        solve(friend_idx + 1, selected_mask)

        return best_count

    solve(0, 0)
    return str(best_count)


