def solution(input_str):
    lines = input_str.strip().split('\n')
    t = int(lines[0])
    result = []

    def solve_case(a):
        n = len(a)

        def remove_all(swap_idx=None):
            if swap_idx is not None:
                b = a[:]
                temp = b[swap_idx]
                b[swap_idx] = b[swap_idx + 1]
                b[swap_idx + 1] = temp
                a = b

            cum = 0
            for i in range(n):
                cum += a[i]
                if i > 0 and cum < 0:
                    return False
            return cum == 0

        def can_remove():
            return remove_all()

        if not can_remove():
            for i in range(n - 1):
                # Try swapping i and i+1
                temp = a[i]
                a[i] = a[i+1]
                a[i+1] = temp
                if can_remove():
                    return True
                # Swap back
                temp = a[i]
                a[i] = a[i+1]
                a[i+1] = temp

        return can_remove()

    idx = 1
    for _ in range(t):
        n = int(lines[idx])
        idx += 1
        a = list(map(int, lines[idx].split()))
        idx += 1

        if solve_case(a):
            result.append("YES")
        else:
            result.append("NO")

    return '\n'.join(result)

