def is_gp(seq):
    n = len(seq)
    if n <= 1:
        return True

    # Check for all zeros
    if all(x == 0 for x in seq):
        return True

    if seq[0] == 0:
        # If first is zero, all must be zero for GP
        if seq[1:] == [0] * (n - 1):
            return True
        return False

    # Calculate expected ratio from first two elements
    if seq[1] == 0:
        return False

    ratio = seq[1] / seq[0]

    # Check all remaining elements
    for i in range(2, n):
        expected = seq[0] * (ratio ** (i))
        if abs(seq[i] - expected) > 1e-9:
            return False

    return True


