import collections

def factorize(num):
    """Return prime factorization as a dict {prime: exponent}"""
    result = collections.defaultdict(int)
    temp = num
    d = 2
    while d * d <= temp:
        while temp % d == 0:
            result[d] += 1
            temp //= d
        d += 1
    if temp > 1:
        result[temp] += 1
    return result

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Store prime factorizations by index (0-indexed)
    # Structure: prime -> list of (index, exponent)
    prime_exponents = collections.defaultdict(list)

    for idx, val in enumerate(a):
        if val == 1:
            continue
        factors = factorize(val)
        for prime, exp in factors.items():
            prime_exponents[prime].append((idx, exp))

    total_ops = 0

    for prime_list in prime_exponents.values():
        odd_exp = 0
        even_exp = 0

        for idx, exp in prime_list:
            # 0-indexed: even indices are odd positions (1st, 3rd, 5th...)
            # odd indices are even positions (2nd, 4th, 6th...)
            if idx % 2 == 0:
                odd_exp += exp
            else:
                even_exp += exp

        total_ops += min(odd_exp, even_exp)

    return str(total_ops) + '\n'

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    n, m = map(int, lines[0].split())
    grid = [list(lines[i]) for i in range(1, n + 1)]

    # Find all connected components of free squares
    visited = set()
    components = []

    for r in range(n):
        for c in range(m):
            if grid[r][c] == '.' and (r, c) not in visited:
                # BFS to find connected component
                comp_cells = []
                queue = [(r, c)]
                visited.add((r, c))

                while queue:
                    cr, cc = queue.pop(0)
                    comp_cells.append((cr, cc))

                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < n and 0 <= nc < m and (nr, nc) not in visited and grid[nr][nc] == '.':
                            visited.add((nr, nc))
                            queue.append((nr, nc))

                # Get bounding box
                rows = [x[0] for x in comp_cells]
                cols = [x[1] for x in comp_cells]
                min_r, max_r = min(rows), max(rows)
                min_c, max_c = min(cols), max(cols)

                # Check if already rectangular
                is_rect = (len(comp_cells) == (max_r - min_r + 1) * (max_c - min_c + 1))

                components.append((min_r, max_r, min_c, max_c, comp_cells, is_rect))

    # For each component, fill its bounding box with free spaces if not already rectangular
    for min_r, max_r, min_c, max_c, comp_cells, is_rect in components:
        if not is_rect:
            for r in range(min_r, max_r + 1):
                for c in range(min_c, max_c + 1):
                    if (r, c) not in comp_cells and grid[r][c] == '*':
                        grid[r][c] = '.'

    return '\n'.join(''.join(row) for row in grid)

import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    operations = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        t = int(parts[0])
        x_prime = int(parts[1])
        y = int(parts[2])
        x = x_prime / 100000.0
        operations.append((t, x, y))

    # earliest[j] = earliest time-step to reach j bananas, -1 if not reachable
    earliest = [-1] * (m + 1)

    # reachable[i] = set of reachable banana counts after operation i
    # We only keep track of values that could possibly be useful
    reachable = {0}

    for step in range(1, n + 1):
        t, x, y = operations[step - 1]
        new_reachable = set()

        for k in reachable:
            try:
                if k > m + 2 * m:  # Optimization: prune values far beyond m
                    continue
            except:
                continue

            # Try applying operation 0 to y times
            if t == 1:
                # Type 1: k := ceil(k + x)
                curr = k
                # By starting from 0, we can compute all possible values for a in [0, y]
                # Precompute cumulative ceilings
                values_to_try = []
                curr = k
                values_to_try.append(curr)
                for _ in range(y):
                    curr = math.ceil(curr + x)
                    if curr <= m:
                        values_to_try.append(curr)
                    else:
                        # If it exceeds m, we can still add values until they exceed
                        # But for practical purposes, when curr > m we can stop
                        break

                # If the first value exceeds m, then all subsequent ones will too
                if not values_to_try:
                    pass  # curr is already > m

                for v in values_to_try:
                    if 1 <= v <= m:
                        if earliest[v] == -1 or earliest[v] == -1:
                            # We found a new value, record it and track earliest step
                            if earliest[v] == -1:
                                earliest[v] = step
                                new_reachable.add(v)

            else:  # t == 2
                # Type 2: k := ceil(k * x)
                values_to_try = []
                curr = k
                if k == 0:
                    curr = 0
                else:
                    curr = k
                    for _ in range(y):
                        curr = math.ceil(curr * x)
                        if curr <= m:
                            values_to_try.append(curr)
                        else:
                            break

                for v in values_to_try:
                    if 1 <= v <= m:
                        if earliest[v] == -1:
                            earliest[v] = step
                            new_reachable.add(v)

        # Update reachable set but also limit its size to prune
        # Keep all reachable values up to m, and add some padding
        reachable_temp = reachable.copy()
        reachable_temp.add(new_reachable)
        reachable = reachable_temp

    # Return result for values 1 to m
    return ' '.join(str(earliest[j]) for j in range(1, m + 1)) + '\n'

