def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    if n == 1 and a[0] == 1:
        return "YES\n"

    def f(x):
        while x % k == 0:
            x //= k
        return x

    # State: tuple of sorted values
    # Memoization stores: boolean (is this state reachable from target), and ops to reconstruct
    memo = {}

    def dfs(state):
        if state in memo:
            return memo[state]

        state = tuple(sorted(state))

        # Base case: single element
        if len(state) == 1:
            result = (state[0] == 1, [])
            memo[state] = result[0]
            return result

        # Try all pairs
        for i in range(len(state)):
            for j in range(i + 1, len(state)):
                x = state[i]
                y = state[j]
                new_val = f(x + y)

                # Build new state by removing x and y
                new_state_list = []
                for idx in range(len(state)):
                    if idx == i or idx == j:
                        continue
                    new_state_list.append(state[idx])
                new_state_list.append(new_val)
                new_state_list.sort()
                new_state_tuple = tuple(new_state_list)

                success, ops = dfs(new_state_tuple)
                if success:
                    ops.append((x, y))
                    memo[state] = (True, ops)
                    return memo[state]

        memo[state] = (False, [])
        return (False, [])

    initial_state = tuple(sorted(a))
    success, ops = dfs(initial_state)

    if success:
        output = ["YES"]
        for x, y in ops:
            output.append(f"{x} {y}")
        return "\n".join(output)
    else:
        return "NO"


