def solution(input_data: str) -> str:
    lines = input_data.strip().split('\n')
    n = int(lines[0])
    field = lines[1]
    n = len(field)

    asterisks = [i for i, c in enumerate(field) if c == '*']
    packmen = [i for i, c in enumerate(field) if c == 'P']

    if not asterisks or not packmen:
        return '0 0'

    # For each asterisk, calculate the minimum time it can be eaten
    # and count how many can be eaten

    min_time_for_asterisk = {}
    for i, ast_pos in enumerate(asterisks):
        min_time = float('inf')

        # Find closest packman on left that can reach right to eat this
        for p in packmen:
            if p < ast_pos:
                min_time = min(min_time, ast_pos - p)
            else:
                break

        # Find closest packman on right that can reach left to eat this
        for p in packmen:
            if p > ast_pos:
                min_time = min(min_time, p - ast_pos)
            else:
                break

        min_time_for_asterisk[i] = min_time

    # All asterisks can theoretically be eaten
    count = len(asterisks)
    time = max(min_time_for_asterisk.values()) if min_time_for_asterisk else 0

    return f'{count} {time}'

def solution(input_str):
    lines = input_str.strip().split('\n')
    t = int(lines[0])
    results = []

    def get_divisors(n):
        """Get all divisors of n that are greater than 1"""
        divs = []
        for d in range(1, int(n**0.5) + 1):
            if n % d == 0:
                if d > 1:
                    divs.append(d)
                if d * d != n and n // d > 1:
                    divs.append(n // d)
        return sorted(divs)

    for i in range(1, t + 1):
        n = int(lines[i])
        divs = get_divisors(n)

        # Check if n has exactly 3 divisors (n = p × q, distinct primes)
        num_divs = len(divs)

        if num_divs == 3:
            # Special case: n = p × q, divisors are [p, q, n]
            # Any circular arrangement will have coprime adjacent pair
            # Output in order p, q, n with 1 move
            # Example: 2 3 6 for n=6
            result_order = f"{divs[0]} {divs[1]} {n}"
            results.append(f"{result_order}\n1")
        else:
            # For other cases, we can arrange divisors so all adjacent
            # pairs share a common factor > 1 (0 moves needed)
            result_order = ' '.join(map(str, divs))
            results.append(f"{result_order}\n0")

    return '\n'.join(results)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m, k, p = map(int, lines[0].split())

    bamboos = []
    for i in range(1, n + 1):
        h, a = map(int, lines[i].split())
        bamboos.append((h, a))

    for _ in range(m):
        # Sort by growth rate (primary) and height (secondary) in descending order
        # This ensures we hit bamboos that will grow the most
        bamboos.sort(key=lambda x: (x[1], x[0]), reverse=True)

        # Hit up to k bamboos
        for _ in range(k):
            if len(bamboos) == 0:
                break
            h, a = bamboos[0]
            if h > 0:
                bamboos[0] = (max(0, h - p), a)
            else:
                bamboos.pop(0)

        # Apply growth to all bamboos
        for i in range(len(bamboos)):
            bamboos[i] = (bamboos[i][0] + bamboos[i][1], bamboos[i][1])

    # Find maximum height
    return str(max(h for h, a in bamboos))

