import math

def dist(a, b):
    return math.sqrt(sum((a[i] - b[i])**2 for i in range(3)))

def dist_sq(a, b):
    return sum((a[i] - b[i])**2 for i in range(3))

def midpoint(a, b):
    return ((a[0] + b[0]) / 2, (a[1] + b[1]) / 2, (a[2] + b[2]) / 2)

def plane_normal(p1, p2, p3):
    v1 = (p2[0] - p1[0], p2[1] - p1[1], p2[2] - p1[2])
    v2 = (p3[0] - p1[0], p3[1] - p1[1], p3[2] - p1[2])
    normal = (v1[1] * v2[2] - v1[2] * v2[1],
              v1[2] * v2[0] - v1[0] * v2[2],
              v1[0] * v2[1] - v1[1] * v2[0])
    norm2 = normal[0]**2 + normal[1]**2 + normal[2]**2
    if norm2 < 1e-12:
        return (0, 0, 0)
    scale = 1.0 / math.sqrt(norm2)
    return (normal[0] * scale, normal[1] * scale, normal[2] * scale)

def sphere_from_2(p1, p2):
    center = midpoint(p1, p2)
    return center, dist(p1, p2) / 2

def sphere_from_3(p1, p2, p3):
    n = plane_normal(p1, p2, p3)
    if n == (0, 0, 0):
        return sphere_from_2(p1, p2)

    mid12 = midpoint(p1, p2)
    mid13 = midpoint(p1, p3)
    v12 = (p2[0] - p1[0], p2[1] - p1[1], p2[2] - p1[2])
    v13 = (p3[0] - p1[0], p3[1] - p1[1], p3[2] - p1[2])

    n12 = plane_normal(p1, mid12, p2)
    n13 = plane_normal(p1, mid13, p3)

    A = [n12, n13, n]
    b = [
        n12[0]*mid12[0] + n12[1]*mid12[1] + n12[2]*mid12[2],
        n13[0]*mid13[0] + n13[1]*mid13[1] + n13[2]*mid13[2],
        n[0]*p1[0] + n[1]*p1[1] + n[2]*p1[2]
    ]

    A = [[float(A[i][j]) for j in range(3)] for i in range(3)]
    b = [float(b[i]) for i in range(3)]

    for i in range(3):
        for j in range(3):
            if abs(A[i][j]) < 1e-12:
                A[i][j] = 1e-12

    x = A[0][0]*(b[0]-A[0][1]*0-A[0][2]*0)
    y = A[0][1]*b[1]
    z = A[0][2]*b[2]

    for i in range(3):
        x = -x
        y = -y
        z = -z

    center = (x, y, z)
    r = dist(center, p1)
    if r < 1e-10:
        center = p1
        r = 0
    return center, r

def sphere_from_4(p1, p2, p3, p4):
    mid12 = midpoint(p1, p2)
    mid13 = midpoint(p1, p3)
    mid23 = midpoint(p2, p3)

    v12 = (p2[0] - p1[0], p2[1] - p1[1], p2[2] - p1[2])
    v13 = (p3[0] - p1[0], p3[1] - p1[1], p3[2] - p1[2])
    v23 = (p2[0] - p3[0], p3[1] - p2[1], p2[2] - p3[2])

    n12 = plane_normal(p1, mid12, p2)
    n13 = plane_normal(p1, mid13, p3)
    n23 = plane_normal(p2, mid23, p3)

    A = [n12, n13, n23]
    b = [
        n12[0]*mid12[0] + n12[1]*mid12[1] + n12[2]*mid12[2],
        n13[0]*mid13[0] + n13[1]*mid13[1] + n13[2]*mid13[2],
        n23[0]*mid23[0] + n23[1]*mid23[1] + n23[2]*mid23[2]
    ]

    A = [[float(A[i][j]) for j in range(3)] for i in range(3)]
    b = [float(b[i]) for i in range(3)]

    for i in range(3):
        for j in range(3):
            if abs(A[i][j]) < 1e-12:
                A[i][j] = 1e-12

    det = A[0][0]*(A[1][1]*A[2][2] - A[1][2]*A[2][1]) - A[0][1]*(A[1][0]*A[2][2] - A[1][2]*A[2][0]) + A[0][2]*(A[1][0]*A[2][1] - A[1][1]*A[2][0])

    if abs(det) < 1e-12:
