    x = (b[0]*(A[1][1]*A[2][2]-A[1][2]*A[2][1]) - A[0][1]*(b[1]*A[2][2]-b[2]*A[2][1]) + A[0][2]*(b[1]*A[2][0]-b[2]*A[2][0])) / det
    y = (A[0][0]*(b[1]*A[2][2]-b[2]*A[2][1]) - b[0]*(A[1][0]*A[2][2]-A[1][2]*A[2][0]) + A[0][2]*(b[1]*A[1][0]-b[2]*A[1][0])) / det
    z = (A[0][0]*(A[1][1]*b[2]-A[1][2]*b[1]) - A[0][1]*(A[1][0]*b[2]-b[1]*A[1][0]) + b[0]*(A[1][1]*A[2][0]-A[1][0]*A[2][1])) / det

    center = (x, y, z)
    r = dist(center, p1)
    if r < 1e-10:
        center = p1
        r = 0
    return center, r

def welzl(points):
    def rec(points, boundary, pos):
        if pos == len(points):
            if len(boundary) == 0:
                return None
            elif len(boundary) == 1:
                return boundary[0], 0
            elif len(boundary) == 2:
                p1, p2 = boundary[0], boundary[1]
                s, r = sphere_from_2(p1, p2)
                return s, r
            elif len(boundary) == 3:
                s, r = sphere_from_3(boundary[0], boundary[1], boundary[2])
                return s, r
            elif len(boundary) == 4:
                s, r = sphere_from_4(boundary[0], boundary[1], boundary[2], boundary[3])
                return s, r

        ps = points[:pos]
        if len(points) - pos - 1 == 0:
            return None

        p = points[pos]
        if rec(points, boundary, pos + 1)[0] is None:
            return None

        c, r = rec(points, boundary, pos + 1)

        if c is None or dist(p, c) > r + 1e-9:
            return rec(points, boundary + [p], pos + 1)
        else:
            return c, r

    return rec(points, [], 0)

