    if s == t:
        return "-1"

    edges = []
    adj = [[] for _ in range(n + 1)]
    edge_map = {}  # edge_key -> (w, original_index)

    # Build graph
    for i in range(m):
        u, v, w = map(int, lines[2 + i].split())
        u1, v1 = min(u, v), max(u, v)
        edges.append((u, v, w, i + 1))
        adj[u].append(v)
        adj[v].append(u)
        edge_key = (u1, v1)
        # Store edge info using original weight
        edge_map[edge_key] = (w, i + 1)

    # BFS to check if t is reachable from s
    def is_connected(removed_keys):
        """Returns True if there's a path from s to t when edges in removed_keys are removed"""
        visited = {s}
        queue = deque([s])
        while queue:
            curr = queue.popleft()
            if curr == t:
                return True
            for nxt in adj[curr]:
                edge_key = (min(curr, nxt), max(curr, nxt))
                if edge_key not in removed_keys and nxt not in visited:
                    visited.add(nxt)
                    queue.append(nxt)
        return False

    # Solution storage
    min_cost = float('inf')
    best_edges = []

    # Check if s and t are already disconnected
    if not is_connected(set()):
        return "0\n0\n"

    # Try removing single edges
    for u, v, w, idx in edges:
        edge_key = (min(u, v), max(u, v))
        removed = {edge_key}
        if not is_connected(removed):
            if w < min_cost:
                min_cost = w
                best_edges = [idx]

    # Try removing pairs of edges if no single edge worked
    if min_cost > float('inf'):
        for i in range(m):
            u1, v1, w1, idx1 = edges[i]
            key1 = (min(u1, v1), max(u1, v1))
            for j in range(i + 1, m):
                u2, v2, w2, idx2 = edges[j]
                key2 = (min(u2, v2), max(u2, v2))
                removed = {key1, key2}
                if not is_connected(removed):
                    total_cost = w1 + w2
                    if total_cost < min_cost:
                        min_cost = total_cost
                        best_edges = [idx1, idx2]

    # Generate output
    if min_cost == float('inf'):
        return "-1\n"
    elif len(best_edges) == 1:
        return f"{min_cost}\n1\n{best_edges[0]}\n"
    else:
        return f"{min_cost}\n2\n{best_edges[0]} {best_edges[1]}\n"

