    contacts = lines[1:n+1]
    predictions = list(map(int, lines[n+1].split()))

    def check(subset):
        actual = [0] * n
        for j in subset:
            for i in range(n):
                if contacts[j][i] == '1':
                    actual[i] += 1

        for i in range(n):
            if actual[i] == predictions[i]:
                return False
        return True

    # Check empty set first (everyone arrives = 0 messages received)
