def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solution(inp):
    input_str = inp.strip()
    if not input_str:
        return "0\n"

    x, y = map(int, input_str.split())

    if y == 0:
        return "0\n"

    if x == 1:
        return f"{y}\n"

    # Memoization cache for intermediate states
    cache = {}

    def solve(current_y):
        if current_y == 0:
            return 0
        if current_y in cache:
            return cache[current_y]

        g = gcd(x, current_y)

        # If current_y is divisible by g, we can jump directly to 0
        if current_y % g == 0:
            cache[current_y] = current_y // g
            return current_y // g
        else:
            # Otherwise subtract g once
            ans = 1 + solve(current_y - g)
            cache[current_y] = ans
            return ans

    result = solve(y)
    return f"{result}\n"

def solution(grid_input):
    lines = grid_input.strip().split('\n')
    if len(lines) < 2:
