        return "0"

    grid = [list(line.strip()) for line in grid_lines]

    # Pre-check: all pre-filled 2x2 blocks must have distinct colors
    def check_filled():
        for r in range(n - 1):
            for c in range(m - 1):
                colors = set()
                for dr in [0, 1]:
                    for dc in [0, 1]:
                        val = grid[r + dr][c + dc]
                        if val and val != '0':
                            colors.add(int(val))
                if len(colors) != 4:
                    return False
        return True

    if not check_filled():
        return "0"

    # Backtracking solver
    result_grid = [row[:] for row in grid]

    def is_valid(r, c, color):
        # Check if setting position (r,c) to color is valid
        # Check direct conflicts in all 2x2 blocks containing (r,c)
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    # This neighbor is in the same 2x2 block
                    if result_grid[nr][nc] != '0' and result_grid[nr][nc] == str(color):
                        return False

                    # Also check if both (r,c) and (nr,nc) force some colors in 2x2
                    base_r, base_c = min(r, nr), min(c, nc)
                    other_cells = [(r, nc), (nr, c), (r, c), (nr, nc)]
                    colors_in_block = set()
                    for orr, onc in other_cells:
                        val = result_grid[orr][onc]
                        if val != '0':
                            colors_in_block.add(int(val))

                    # If one of them has color 'color', check no conflict
                    if result_grid[r][c] == str(color):
                        colors_in_block.discard(color)

    def dfs(cell_idx):
        if cell_idx >= n * m:
            return True

        r, c = cell_idx // m, cell_idx % m

        if grid[r][c] != '0':
            return dfs(cell_idx + 1)

        for color in [1, 2, 3, 4]:
            valid = True

            # Check all adjacent 2x2 constraints
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        if result_grid[nr][nc] != '0' and result_grid[nr][nc] == str(color):
                            valid = False
                            break
                        if dr == 0 and dc == 1:
                            # Same row, right neighbor
                            base_r, base_c = min(r, nr), min(c, nc)
                        elif dr == 0 and dc == -1:
                            # Same row, left neighbor  
                            base_r, base_c = min(r, nr), min(c, nc)
                        elif dr == 1 and dc == 0:
                            # Directly below
                            base_r, base_c = r, c
                        elif dr == -1 and dc == 0:
                            # Directly above
                            base_r, base_c = r, c
                        elif dr == 1 and dc == 1:
                            # Diagonal down-right
                            base_r, base_c = r, c
                        elif dr == 1 and dc == -1:
                            # Diagonal down-left
                            base_r, base_c = r, c
                        elif dr == -1 and dc == 1:
                            # Diagonal up-right
                            base_r, base_c = r, c
                        elif dr == -1 and dc == -1:
                            # Diagonal up-left
                            base_r, base_c = r, c

                        if dr == 0 and dc == -1 or (dr < 0 and dc == 0):
                            base_r, base_c = min(r, nr), min(c, nc)

                    # Check that 2x2 block has all 4 colors if fully filled
                    if 0 <= base_r + 1 < n and 0 <= base_c + 1 < m:
                        block_colors = set()
                        for i in [0, 1]:
                            for j in [0, 1]:
                                cell_val = result_grid[base_r + i][base_c + j]
                                if cell_val != '0':
                                    block_colors.add(int(cell_val))

                        if len(block_colors) == 4 and color in block_colors:
                            valid = False
                            break

                    if not valid:
                        break

            if valid:
                result_grid[r][c] = str(color)
                if dfs(cell_idx + 1):
                    return True
                result_grid[r][c] = '0'

        return False

    if dfs(0):
        return "\n".join("".join(row) for row in result_grid)
    else:
        return "0"

