    lines = input_data.strip().split('\n')
    ptr = 0
    t = int(lines[ptr])
    ptr += 1
    output = []

    for _ in range(t):
        n, m = map(int, lines[ptr].split())
        ptr += 1

        matrix = []
        for i in range(n):
            row = list(map(int, lines[ptr].split()))
            matrix.append(row)
            ptr += 1

        ops = lines[ptr]
        ptr += 1

        for op in ops:
            if op == 'R':
                # Right shift columns
                new_matrix = [[0] * n for _ in range(n)]
                for i in range(n):
                    for j in range(1, n + 1):
                        new_matrix[i][j - 1] = matrix[i][(j - 2) % n + 1 - 1] if (j - 2) % n + 1 != 0 else matrix[i][n - 1]
                matrix = new_matrix
            elif op == 'L':
                # Left shift columns
                new_matrix = [[0] * n for _ in range(n)]
                for i in range(n):
                    for j in range(n):
                        new_matrix[i][j] = matrix[i][(j + 1) % n]
                matrix = new_matrix
            elif op == 'D':
                # Down shift rows
                new_matrix = [[0] * n for _ in range(n)]
                for i in range(n):
                    for j in range(n):
                        new_matrix[i][j] = matrix[(i - 1) % n][j]
                matrix = new_matrix
            elif op == 'U':
                # Up shift rows
                new_matrix = [[0] * n for _ in range(n)]
                for i in range(n):
                    for j in range(n):
                        new_matrix[i][j] = matrix[(i + 1) % n][j]
                matrix = new_matrix
            elif op == 'I':
                # Invert each row
                for i in range(n):
                    row = matrix[i]
                    inverse = [0] * n
                    for j in range(n):
                        inverse[row[j] - 1] = j + 1
                    matrix[i] = inverse
            elif op == 'C':
                # Invert each column
                inverse = [[0] * n for _ in range(n)]
                for j in range(n):
                    col = [matrix[i][j] for i in range(n)]
                    for i in range(n):
                        inverse[col[i] - 1][j] = i + 1
                matrix = inverse

        # Output the matrix
        for row in matrix:
            output.append(' '.join(map(str, row)))

    return '\n'.join(output) + '\n'

