def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    polygon = [[int(x) for x in line.split()] for line in lines[1:n + 1]]

    MOD = 1000000007

    def orientation(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def on_segment(p, a, b):
        return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and \
               min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

    def do_intersect(p1, p2, p3, p4):
        o1 = orientation(p1, p2, p3)
        o2 = orientation(p1, p2, p4)
        o3 = orientation(p3, p4, p1)
        o4 = orientation(p3, p4, p2)

        if ((o1 > 0 and o2 < 0) or (o1 < 0 and o2 > 0)) and \
           ((o3 > 0 and o4 < 0) or (o3 < 0 and o4 > 0)):
            return True

        if o1 == 0 and on_segment(p3, p1, p2):
            return True
        if o2 == 0 and on_segment(p4, p1, p2):
            return True
        if o3 == 0 and on_segment(p1, p3, p4):
            return True
        if o4 == 0 and on_segment(p2, p3, p4):
            return True

        return False

    def is_valid_diag(i, j):
        """Check if diagonal between vertices i and j is completely inside polygon"""
        if abs(i - j) == 1 or (i == 0 and j == n - 1):
            return False

        for k in range(n):
            if k == i or k == j:
                continue

            p1, p2 = polygon[i], polygon[j]
            p3, p4 = polygon[k], polygon[(k + 1) % n]

            if do_intersect(p1, p2, p3, p4):
                return False

        return True

    # dp[i][j] = number of triangulations of vertices from i to j (inclusive in range sense)
    dp = [[0] * n for _ in range(n)]

    # Base case: chains of length 1 (two consecutive vertices)
    for i in range(n):
        dp[i][i] = 1

    # Fill for chains of increasing length
    for length in range(1, n):
        for i in range(n - length + 1 if i + length < n else n - length):
            j = i + length
            if j >= n:
                break
            for k in range(i + 1, j):
                if k >= n or k == i or k == j:
                    continue
                left = dp[i][k] if dp[i][k] > 0 else 1
                right = dp[k][j] if dp[k][j] > 0 else 1
                if is_valid_diag(i, k) and is_valid_diag(k, j):
                    dp[i][j] = (dp[i][j] + left * right) % MOD

    # For the polygon, count triangulations by choosing middle vertices
    ans = 0
    for k in range(1, n - 1):
        left = 1 if k == 1 else dp[0][k]
        right = 1 if k == n - 2 else dp[k][n - 1]
        if is_valid_diag(0, k) and is_valid_diag(k, n - 1):
            ans = (ans + left * right) % MOD

    return str(ans)

