                    new_dp[new_count] = min(new_dp.get(new_count, float('inf')), new_cost)

            # Option 3: buy with coupon only if ancestor coupon used
            # For node 0 (root), no need for parent
            # For i > 0, need to buy parent with coupon first

            can_use_coupon = (i == 0) or (x != -1 and 'P' + x in dp)
