def solution(input_str):
    n, m = map(int, input_str.strip().split())

    if min(n, m) == 1:
        m = max(n, m)
        if m <= 2:
            return "0"
        elif m == 3:
            return "0"
        else:
            return str(2 * (m // 3))
    else:
        if n * m % 2 == 1:
            return str(n * m - 1)
        else:
            return str(n * m)

