    # Total adjacent pairs (always visible)
    count = n

    # For non-adjacent pairs, check if they can see each other
    # A pair (i, j) with i < j can see each other if:
    # 1. All hills in arc [i+1, j-1] have height <= max(height[i], height[j])
    #    OR
    # 2. All hills in arc [j+1, n-1] and [0, i-1] have height <= max(height[i], height[j])

    for i in range(n):
        for j in range(i + 1, n):
            if j == i + 1:  # already counted as adjacent
                continue

            # Check first arc from i to j (clockwise)
            arc1_blocked = False
            for k in range(i + 1, j):
                if heights[k] > max(heights[i], heights[j]):
                    arc1_blocked = True
                    break

            if not arc1_blocked:
                count += 1
            else:
                # Check second arc (wrapping around)
                arc2_blocked = False
                for k in range(j + 1, n):
                    if heights[k] > max(heights[i], heights[j]):
                        arc2_blocked = True
                        break
                for k in range(0, i):
                    if heights[k] > max(heights[i], heights[j]):
                        arc2_blocked = True
                        break

                if not arc2_blocked:
                    count += 1

    return f'{count}\n'

def can_first_player_win(s, e, memo={}):
        if s > e:
            return False  # Current player exceeded, so they lose
        if (s, e) in memo:
            return memo[(s, e)]

        can_force_win = False
        doubled = 2 * s
        incremented = s + 1

        for move in [doubled, incremented]:
            if move > e:
                # This move causes the current player to lose
                continue
            else:
                # Opponent's turn from 'move' with limit e
                opponent_can_win = can_first_player_win(move, e, memo)
                if not opponent_can_win:
                    can_force_win = True
                    break

        memo[(s, e)] = can_force_win
        return can_force_win

def solution(input_str):
    from typing import List, Tuple

    data = input_str.strip().split()
    n = int(data[0])
    r = int(data[1])

    # Generate all integer points within distance r from origin
    points: List[Tuple[int, int]] = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x * x + y * y <= r * r:
                points.append((x, y))

    m = len(points)

    # Precompute squared distances between all pairs of positions
    dist: List[List[int]] = [[0] * m for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            d = (points[i][0] - points[j][0]) ** 2 + (points[i][1] - points[j][1]) ** 2
            dist[i][j] = dist[j][i] = d

    best_sum = 0
    best_arrangement: List[int] = list(range(n))

    # Try 2 clusters
    max_i = min(m, n)
    max_j = min(m, n)
    for i in range(max_i):
        for j in range(i + 1, max_j):
            dij = dist[i][j]
            if dij == 0:
                continue
            for k in range(1, n):
                s = k * (n - k) * dij
                if s > best_sum:
                    best_sum = s
                    best_arrangement = [i] * k + [j] * (n - k)

    # Try 3 clusters (more efficient than full enumeration by clustering)
    for i in range(m):
        for j in range(i + 1, m):
            dij = dist[i][j]
            if dij == 0:
                continue
            for k in range(j + 1, m):
                dik = dist[i][k]
                jik = dist[j][k]
                if dik == 0 or jik == 0:
                    continue

                # Try all partitions of n into 3 positive integers
                for c1 in range(1, n - 1):
                    for c2 in range(1, n - c1):
                        c3 = n - c1 - c2
                        s = c1 * c2 * dij + c1 * c3 * dik + c2 * c3 * jik
                        if s > best_sum:
                            best_sum = s
                            best_arrangement = [i] * c1 + [j] * c2 + [k] * c3

    # Format and return output
    output_lines = [str(best_sum)]
    for idx in best_arrangement:
        output_lines.append(f"{points[idx][0]} {points[idx][1]}")
    return '\n'.join(output_lines) + '\n'

from itertools import combinations

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0'

    n, m = map(int, lines[0].split())

    attempts = []
    responses = []
    for i in range(1, m + 1):
        line = lines[i].split()
        attempts.append(line[0])
        responses.append(int(line[1]))

    if m == 0:
        return str(2 ** n)

    assert 0 <= responses[0] <= n, "Invalid response value"

    count = 0
    positions = range(n)

    # Try all ways to choose which positions match the first attempt
    for match_positions in combinations(positions, responses[0]):
        # Build candidate code
        candidate = []
        for i in range(n):
            if i in match_positions:
                # Position matches, same bit value
                candidate.append(attempts[0][i])
            else:
                # Position doesn't match, opposite bit value
                candidate.append('1' if attempts[0][i] == '0' else '0')

        # Verify against all other constraints
        valid = True
        for i in range(1, m):
            matches = sum(1 for j in range(n) if candidate[j] == attempts[i][j])
            if matches != responses[i]:
                valid = False
                break

        if valid:
            count += 1

    return str(count)

# Test with examples
if __name__ == "__main__":
    print(solution('6 2\n000000 2\n010100 4\n'))  # Should be 6
    print(solution('6 3\n000000 2\n010100 4\n111100 0\n'))  # Should be 0
    print(solution('6 3\n000000 2\n010100 4\n111100 2\n'))  # Should be 1

