from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    first_line = lines[0].strip().split()
    n, d = int(first_line[0]), int(first_line[1])

    if len(lines) > 1:
        second_line = lines[1].strip().split()
        items = [int(x) for x in second_line]
    else:
        items = []

    if not items:
        return "0 0"

    # Compute all possible subset sums using DP
    possible_sums = {0}
    for item in items:
        possible_sums |= {s + item for s in possible_sums}
    possible_sums = sorted(possible_sums)

    # BFS to find minimum exchanges for each reachable sum
    min_days = {0: 0}
    queue = deque([0])

    max_score = 0
    max_days = 0

    while queue:
        s = queue.popleft()

        if s > max_score:
            max_score = s
            max_days = min_days[s]

        current_days = min_days[s] + 1

        # Try to reach all possible sums t where t > s and t <= s + d
        for t in possible_sums:
            if t > s and t <= s + d:
                if t not in min_days:
                    min_days[t] = current_days
                    queue.append(t)

    return f"{max_score} {max_days}"

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, s = map(int, lines[0].split())
    buildings = []

    for i in range(1, n + 1):
        v, c = map(int, lines[i].split())
        buildings.append((v, c))

    # Binary search on time
    low = 1
    high = s

    def check(time):
        if time == 0:
            return False
        if s <= 0:
            return True

        cookies = 0
        rate = 1  # Start with 1 cookie/second from clicking
        remaining = set(range(len(buildings)))
        owned = set()

        for second in range(time):
            # Find all buildings we can afford
            affordable = []
            for i in range(len(buildings)):
                if i not in remaining and i not in owned:
                    continue
                cost, val = buildings[i]
                if cookies >= cost:
                    affordable.append((i, cost, val))

            if affordable:
                # Sort by value per cost (efficiency) or just by value
                affordable.sort(key=lambda x: x[2], reverse=True)

                for idx, cost, val in affordable[:len(affordable)]:
                    # Double check we can afford
                    if cookies >= cost and idx not in owned:
                        cookies -= cost
                        owned.add(idx)
                        rate += val

            cookies += rate

            if cookies >= s:
                return True

        return cookies >= s

    while low < high:
        mid = (low + high) // 2
        if check(mid):
            high = mid
        else:
            low = mid + 1

    return str(low) + '\n'
